import{_ as a,a as t,c as o,ac as s}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"第一册：英语初阶 · 综合复习与自测 · 第60–66课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第一册：英语初阶 · 综合复习与自测 · 第60–66课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-1/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第53–59课","link":"/life/english/new-concept/book-1/review-part-08"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第67–73课","link":"/life/english/new-concept/book-1/review-part-10"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 综合复习与自测 · 第53–59课","link":"/life/english/new-concept/book-1/review-part-08"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第67–73课","link":"/life/english/new-concept/book-1/review-part-10"}},"headers":[],"relativePath":"life/english/new-concept/book-1/review-part-09.md","filePath":"life/english/new-concept/book-1/review-part-09.md"}'),n={name:"life/english/new-concept/book-1/review-part-09.md"};function i(r,e,l,h,m,p){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="第一册-英语初阶-·-综合复习与自测-·-第60–66课" tabindex="-1">第一册：英语初阶 · 综合复习与自测 · 第60–66课 <a class="header-anchor" href="#第一册-英语初阶-·-综合复习与自测-·-第60–66课" aria-label="Permalink to &quot;第一册：英语初阶 · 综合复习与自测 · 第60–66课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-60-·-可数和不可数名词的数量" tabindex="-1">Lesson 60 · 可数和不可数名词的数量 <a class="header-anchor" href="#lesson-60-·-可数和不可数名词的数量" aria-label="Permalink to &quot;Lesson 60 · 可数和不可数名词的数量 {#lesson-60-·-可数和不可数名词的数量}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> How much flour do you need?</p><h3 id="练习-1-59" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-59" aria-label="Permalink to &quot;练习 1 {#练习-1-59}&quot;">​</a></h3><p>选择 much/many：How ___ flour?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> much</p><p><strong>解析：</strong> 按本课规则判断：可数名词用 many、a few 或具体数词，通常有复数形式；不可数名词用 much、a little 或量词。some 可用于两者。have 作拥有的实义动词时，否定可用 don&#39;t have。购物清单中 a kilo of apples 的数量核心是 kilo，复数时写 two kilos of apples。不要把中文数量词直接省略。</p></details><p><strong>表达迁移：</strong> 围绕“核对购物清单并表达数量”写两至三句，再读给同伴听。至少使用一次可数和不可数名词的数量，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>How much flour do you need? We need five envelopes and some writing paper.</p><p>How much flour 是疑问宾语，flour 不可数；do 放在主语 you 之前，need 用原形。 Need 的宾语由 five envelopes 和 some writing paper 并列组成：前者可数复数，后者不可数。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-060">回看本课</a></p><h2 id="lesson-61-·-have-表身体状况与-must" tabindex="-1">Lesson 61 · have 表身体状况与 must <a class="header-anchor" href="#lesson-61-·-have-表身体状况与-must" aria-label="Permalink to &quot;Lesson 61 · have 表身体状况与 must {#lesson-61-·-have-表身体状况与-must}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Mina has a headache today.</p><h3 id="练习-1-60" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-60" aria-label="Permalink to &quot;练习 1 {#练习-1-60}&quot;">​</a></h3><p>填 have 的形式：Mina ___ a headache.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> has</p><p><strong>解析：</strong> 按本课规则判断：have 可表达某些身体状况，如 have a headache；be 与形容词搭配，如 be tired。must + 原形可表达强烈要求，但本页只是语言练习，不提供诊断或治疗建议。询问状况可用 What is the matter with ...?，with 后用宾格。第三人称肯定 have 变 has，疑问用 does ... have。</p></details><p><strong>表达迁移：</strong> 围绕“描述身体不适并理解必要事项”写两至三句，再读给同伴听。至少使用一次have 表身体状况与 must，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Mina has a headache today. What is the matter with him?</p><p>Mina 是第三人称单数，have 变 has；a headache 是表示身体状况的名词短语，today 表时间。 What is the matter 构成询问状况的固定问句；with him 指明对象，him 是介词后的宾格。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-061">回看本课</a></p><h2 id="lesson-62-·-have-表身体状况与-must" tabindex="-1">Lesson 62 · have 表身体状况与 must <a class="header-anchor" href="#lesson-62-·-have-表身体状况与-must" aria-label="Permalink to &quot;Lesson 62 · have 表身体状况与 must {#lesson-62-·-have-表身体状况与-must}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> What is the matter with him?</p><h3 id="练习-1-61" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-61" aria-label="Permalink to &quot;练习 1 {#练习-1-61}&quot;">​</a></h3><p>选择 he/him：What is the matter with ___?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> him</p><p><strong>解析：</strong> 按本课规则判断：have 可表达某些身体状况，如 have a headache；be 与形容词搭配，如 be tired。must + 原形可表达强烈要求，但本页只是语言练习，不提供诊断或治疗建议。询问状况可用 What is the matter with ...?，with 后用宾格。第三人称肯定 have 变 has，疑问用 does ... have。</p></details><p><strong>表达迁移：</strong> 围绕“描述身体不适并理解必要事项”写两至三句，再读给同伴听。至少使用一次have 表身体状况与 must，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>What is the matter with him? Mina has a headache today.</p><p>What is the matter 构成询问状况的固定问句；with him 指明对象，him 是介词后的宾格。 Mina 是第三人称单数，have 变 has；a headache 是表示身体状况的名词短语，today 表时间。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-062">回看本课</a></p><h2 id="lesson-63-·-must-not-与-do-not-have-to" tabindex="-1">Lesson 63 · must not 与 do not have to <a class="header-anchor" href="#lesson-63-·-must-not-与-do-not-have-to" aria-label="Permalink to &quot;Lesson 63 · must not 与 do not have to {#lesson-63-·-must-not-与-do-not-have-to}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> You must not make noise in this room.</p><h3 id="练习-1-62" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-62" aria-label="Permalink to &quot;练习 1 {#练习-1-62}&quot;">​</a></h3><p>表达禁止：You ___ not enter.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> must</p><p><strong>解析：</strong> 按本课规则判断：must not 表示禁止，don&#39;t have to 或 needn&#39;t 表示不必，两者意义不同。You mustn&#39;t enter 是不得进入；You don&#39;t have to enter 是可以不进入。祈使句 Don&#39;t ... 也用于禁令。mustn&#39;t 后跟动词原形。理解规定时先判断是禁止某动作，还是免除义务，不能只因都有 not 就视为同义。</p></details><p><strong>表达迁移：</strong> 围绕“区分禁止和没有必要”写两至三句，再读给同伴听。至少使用一次must not 与 do not have to，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>You must not make noise in this room. You do not have to wait outside.</p><p>Must not 表禁止，make 用原形；noise 常作不可数名词，in this room 限定规则适用的地方。 Do not have to 表示没有义务，并非禁止；wait 用原形，outside 为地点副词。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-063">回看本课</a></p><h2 id="lesson-64-·-must-not-与-do-not-have-to" tabindex="-1">Lesson 64 · must not 与 do not have to <a class="header-anchor" href="#lesson-64-·-must-not-与-do-not-have-to" aria-label="Permalink to &quot;Lesson 64 · must not 与 do not have to {#lesson-64-·-must-not-与-do-not-have-to}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> You do not have to wait outside.</p><h3 id="练习-1-63" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-63" aria-label="Permalink to &quot;练习 1 {#练习-1-63}&quot;">​</a></h3><p>把“你不必等待”译成英语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> You do not have to wait.</p><p><strong>解析：</strong> 按本课规则判断：must not 表示禁止，don&#39;t have to 或 needn&#39;t 表示不必，两者意义不同。You mustn&#39;t enter 是不得进入；You don&#39;t have to enter 是可以不进入。祈使句 Don&#39;t ... 也用于禁令。mustn&#39;t 后跟动词原形。理解规定时先判断是禁止某动作，还是免除义务，不能只因都有 not 就视为同义。</p></details><p><strong>表达迁移：</strong> 围绕“区分禁止和没有必要”写两至三句，再读给同伴听。至少使用一次must not 与 do not have to，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>You do not have to wait outside. You must not make noise in this room.</p><p>Do not have to 表示没有义务，并非禁止；wait 用原形，outside 为地点副词。 Must not 表禁止，make 用原形；noise 常作不可数名词，in this room 限定规则适用的地方。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-064">回看本课</a></p><h2 id="lesson-65-·-时间表达与-can-表许可" tabindex="-1">Lesson 65 · 时间表达与 can 表许可 <a class="header-anchor" href="#lesson-65-·-时间表达与-can-表许可" aria-label="Permalink to &quot;Lesson 65 · 时间表达与 can 表许可 {#lesson-65-·-时间表达与-can-表许可}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Can I stay until a quarter past nine?</p><h3 id="练习-1-64" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-64" aria-label="Permalink to &quot;练习 1 {#练习-1-64}&quot;">​</a></h3><p>把 a quarter past nine 写为数字时间。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 9:15</p><p><strong>解析：</strong> 按本课规则判断：can 可表示许可，能否这样做需由语境区分能力和允许。询问许可 Can I ...?；答应或拒绝时注意语气。时间表达 half past eight 是八点半，a quarter to nine 是差一刻九点，即八点四十五。at 用在具体钟点前。must be home 强调要求，be home 不是动作 go home。</p></details><p><strong>表达迁移：</strong> 围绕“商量回家时间与表达许可”写两至三句，再读给同伴听。至少使用一次时间表达与 can 表许可，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Can I stay until a quarter past nine? You must be home by half past ten.</p><p>Can I 开头询问许可；stay 为原形，until a quarter past nine 表一直待到9:15。 Must 后接 be 原形；home 表在家，by half past ten 意为最迟10:30，不是必须恰好10:30。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-065">回看本课</a></p><h2 id="lesson-66-·-时间表达与-can-表许可" tabindex="-1">Lesson 66 · 时间表达与 can 表许可 <a class="header-anchor" href="#lesson-66-·-时间表达与-can-表许可" aria-label="Permalink to &quot;Lesson 66 · 时间表达与 can 表许可 {#lesson-66-·-时间表达与-can-表许可}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> You must be home by half past ten.</p><h3 id="练习-1-65" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-65" aria-label="Permalink to &quot;练习 1 {#练习-1-65}&quot;">​</a></h3><p>把 half past ten 写为数字时间。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 10:30</p><p><strong>解析：</strong> 按本课规则判断：can 可表示许可，能否这样做需由语境区分能力和允许。询问许可 Can I ...?；答应或拒绝时注意语气。时间表达 half past eight 是八点半，a quarter to nine 是差一刻九点，即八点四十五。at 用在具体钟点前。must be home 强调要求，be home 不是动作 go home。</p></details><p><strong>表达迁移：</strong> 围绕“商量回家时间与表达许可”写两至三句，再读给同伴听。至少使用一次时间表达与 can 表许可，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>You must be home by half past ten. Can I stay until a quarter past nine?</p><p>Must 后接 be 原形；home 表在家，by half past ten 意为最迟10:30，不是必须恰好10:30。 Can I 开头询问许可；stay 为原形，until a quarter past nine 表一直待到9:15。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-066">回看本课</a></p>',60)])])}const d=a(n,[["render",i]]);export{c as __pageData,d as default};
